select file from glob('s3://aws-public-blockchain/v1.0/eth/blocks/date=2026-08-0*/*.parquet');
describe select * from read_parquet('s3://aws-public-blockchain/v1.0/eth/blocks/date=2026-08-01/*.parquet');
copy (select * exclude (logs_bloom, last_modified) from read_parquet('s3://aws-public-blockchain/v1.0/eth/blocks/date=2026-08-01/*.parquet')) to '/Users/Shared/academy/learner/projects/ethereum_iceberg/data/blocks_2026-08-01.parquet';
copy (select * exclude (input) from read_parquet('s3://aws-public-blockchain/v1.0/eth/transactions/date=2026-10-01/*.parquet')) to '/Users/Shared/academy/learner/projects/ethereum_iceberg/data/transactions_2026-10-01.parquet';
copy (select date as block_date, count(*) as blocks, sum(transaction_count) as transactions, round(avg(100.0 * gas_used / gas_limit), 2) as avg_gas_used_pct, round(avg(base_fee_per_gas) / 1e9, 4) as avg_base_fee_gwei from read_parquet('s3://aws-public-blockchain/v1.0/eth/blocks/date=2026-*/*.parquet') where date between '2026-08-01' and '2026-10-31' group by 1 order by 1) to '/Users/Shared/academy/learner/projects/ethereum_iceberg/data/daily_block_stats.csv' (header);
copy (select * from (values ('0xdac17f958d2ee523a2206206994597c13d831ec7', 'Tether USD (USDT)', 'stablecoin'), ('0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48', 'USD Coin (USDC)', 'stablecoin'), ('0xc02aaa39b223fe8d0a0e5c4f27ead9083c756cc2', 'Wrapped Ether (WETH)', 'token'), ('0x0000000071727de22e5e9d8baf0edac6f37da032', 'ERC-4337 EntryPoint v0.7', 'account abstraction'), ('0x7a250d5630b4cf539739df2c5dacb4c659f2488d', 'Uniswap V2 Router 02', 'exchange'), ('0x00000000219ab540356cbb839cbe05303d7705fa', 'Beacon chain deposit contract', 'staking')) as t(address, label, category)) to '/Users/Shared/academy/learner/projects/ethereum_iceberg/data/known_addresses.json';
